int main() {
    int N;
    scanf("%d", &N);

    char ops[10000];
    scanf("%s", ops);

    int A[100][100];

    // Initialize
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            A[i][j] = i * N + j + 1;

    int len = strlen(ops);
    for (int k = 0; k < len; k++) {
        char op = ops[k];
        int temp;
        if (op == 'L') {
            // Each row shifts left by 1
            for (int i = 0; i < N; i++) {
                temp = A[i][0];
                for (int j = 0; j < N-1; j++)
                    A[i][j] = A[i][j+1];
                A[i][N-1] = temp;
            }
        } else if (op == 'R') {
            // Each row shifts right by 1
            for (int i = 0; i < N; i++) {
                temp = A[i][N-1];
                for (int j = N-1; j > 0; j--)
                    A[i][j] = A[i][j-1];
                A[i][0] = temp;
            }
        } else if (op == 'U') {
            // Each column shifts up by 1
            for (int j = 0; j < N; j++) {
                temp = A[0][j];
                for (int i = 0; i < N-1; i++)
                    A[i][j] = A[i+1][j];
                A[N-1][j] = temp;
            }
        } else if (op == 'D') {
            // Each column shifts down by 1
            for (int j = 0; j < N; j++) {
                temp = A[N-1][j];
                for (int i = N-1; i > 0; i--)
                    A[i][j] = A[i-1][j];
                A[0][j] = temp;
            }
        }
    }

    // Output
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (j > 0) printf(" ");
            printf("%d", A[i][j]);
        }
        printf("\n");
    }

    return 0;
}

