#define MAX_N 1000

int main() {
    int N;
    char ops[100001];

    // Read input
    scanf("%d", &N);
    scanf("%s", ops);

    int len = strlen(ops);

    // Track cumulative shifts for rows and columns
    int row_shift = 0;  // net vertical shift (positive = down, negative = up)
    int col_shift = 0;  // net horizontal shift (positive = right, negative = left)

    for (int i = 0; i < len; i++) {
        switch(ops[i]) {
            case 'L': col_shift--; break;
            case 'R': col_shift++; break;
            case 'U': row_shift--; break;
            case 'D': row_shift++; break;
        }
    }

    // Normalize shifts to be within [0, N-1]
    row_shift = ((row_shift % N) + N) % N;
    col_shift = ((col_shift % N) + N) % N;

    // Build and output the result
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            // Original position (r, c) maps to shifted position (i, j)
            // We need: (r + row_shift) % N = i  =>  r = (i - row_shift + N) % N
            // Similarly: c = (j - col_shift + N) % N
            int r = (i - row_shift + N) % N;
            int c = (j - col_shift + N) % N;

            // Value at original position (r, c) = r * N + (c + 1)
            int value = r * N + c + 1;

            if (j > 0) printf(" ");
            printf("%d", value);
        }
        printf("\n");
    }

    return 0;
}

