        if (ops[i] == 'L') colShift--;
        else if (ops[i] == 'R') colShift++;
        else if (ops[i] == 'U') rowShift--;
        else if (ops[i] == 'D') rowShift++;
    }

    rowShift %= N;
    colShift %= N;
    if (rowShift < 0) rowShift += N;
    if (colShift < 0) colShift += N;

    for (int i = 0; i < N; i++) {
        int srcRow = (i - rowShift + N) % N;
        for (int j = 0; j < N; j++) {
            int srcCol = (j - colShift + N) % N;
            int val = srcRow * N + srcCol + 1;
            if (j) printf(" ");
            printf("%d", val);
        }
        printf("\n");
    }

    return 0;
}

