        }
    }

    // Output the matrix with applied shifts
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            // Original value at (i, j) is i*N + j + 1
            // After shifts, the element that appears at (i, j) came from
            // original row = (i - row_shift + N) % N
            // original col = (j - col_shift + N) % N
            int orig_i = (i - row_shift + N) % N;
            int orig_j = (j - col_shift + N) % N;
            int val = orig_i * N + orig_j + 1;
            cout << val << (j + 1 == N ? '\n' : ' ');
