        String ops = sc.next();

        int[][] mat = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                mat[i][j] = i * n + j + 1;

        for (char op : ops.toCharArray()) {
            if (op == 'L') {
                // shift each row left
                for (int i = 0; i < n; i++) {
                    int first = mat[i][0];
                    for (int j = 0; j < n-1; j++) mat[i][j] = mat[i][j+1];
                    mat[i][n-1] = first;
                }
            } else if (op == 'R') {
                // shift each row right
                for (int i = 0; i < n; i++) {
                    int last = mat[i][n-1];
                    for (int j = n-1; j > 0; j--) mat[i][j] = mat[i][j-1];
                    mat[i][0] = last;
                }
            } else if (op == 'U') {
                // shift each column up
                for (int j = 0; j < n; j++) {
                    int first = mat[0][j];
                    for (int i = 0; i < n-1; i++) mat[i][j] = mat[i+1][j];
                    mat[n-1][j] = first;
                }
            } else if (op == 'D') {
                // shift each column down
                for (int j = 0; j < n; j++) {
                    int last = mat[n-1][j];
                    for (int i = n-1; i > 0; i--) mat[i][j] = mat[i-1][j];
                    mat[0][j] = last;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j > 0) sb.append(' ');
                sb.append(mat[i][j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

import java.util.Scanner;

public class ShiftMatrix {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        sc.nextLine(); // consume newline
        String ops = sc.nextLine().trim();

        int rowShift = 0, colShift = 0;
        boolean rowFlip = false, colFlip = false;

        for (char op : ops.toCharArray()) {
            switch (op) {
                case 'L':
                    if (colFlip) colShift++;
                    else colShift--;
                    break;
                case 'R':
                    if (colFlip) colShift--;
                    else colShift++;
                    break;
                case 'U':
                    if (rowFlip) rowShift++;
                    else rowShift--;
                    break;
                case 'D':
                    if (rowFlip) rowShift--;
                    else rowShift++;
                    break;
            }
        }

        // Normalize shifts
        rowShift = ((rowShift % N) + N) % N;
        colShift = ((colShift % N) + N) % N;

        // Build result matrix
        int[][] result = new int[N][N];
        for (int i = 0; i < N; i++) {
            int origRow = rowFlip ? (N - 1 - i) : i;
            for (int j = 0; j < N; j++) {
                int origCol = colFlip ? (N - 1 - j) : j;
                int val = (origRow * N) + origCol + 1;
                int r = (i + rowShift) % N;
                int c = (j + colShift) % N;
                result[r][c] = val;
            }
        }

        // Print output
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j > 0) System.out.print(" ");
                System.out.print(result[i][j]);
            }
            System.out.println();
        }
    }
}

