public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer nObj = fs.nextIntNullable();
        if (nObj == null) return;
        int n = nObj;

        StringBuilder opsBuilder = new StringBuilder();
        String token;
        while ((token = fs.next()) != null) {
            if (opsBuilder.length() > 0) opsBuilder.append(' ');
            opsBuilder.append(token);
        }
        String ops = opsBuilder.toString();

        long rowShift = 0; // positive means shifted down
        long colShift = 0; // positive means shifted right

        for (int i = 0; i < ops.length(); i++) {
            char c = ops.charAt(i);
            switch (c) {
                case 'L':
                case 'l':
                    colShift--;
                    break;
                case 'R':
                case 'r':
                    colShift++;
                    break;
                case 'U':
                case 'u':
                    rowShift--;
                    break;
                case 'D':
                case 'd':
                    rowShift++;
                    break;
                default:
                    // ignore any non-operation characters
            }
        }

        int rs = mod(rowShift, n);
        int cs = mod(colShift, n);

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int srcRow = mod(i - rs, n);
            for (int j = 0; j < n; j++) {
                int srcCol = mod(j - cs, n);
                long val = (long) srcRow * n + (srcCol + 1L);
                if (j > 0) out.append(' ');
                out.append(val);
            }
            if (i + 1 < n) out.append('\n');
        }

        System.out.print(out.toString());
    }

    static int mod(long x, int m) {
        int r = (int)(x % m);
        if (r < 0) r += m;
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (Character.isWhitespace(c));

            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }
    }
}

