import sys

def solve():
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx += 1

    # Read operations - could be remaining tokens
    ops = data[idx:]

    # Initialize matrix (0-indexed internally)
    matrix = [[(i * N + j + 1) for j in range(N)] for i in range(N)]

    for op in ops:
        op = op.upper()
        if op == 'L' or op == 'LEFT':
            # Shift each row left
            for i in range(N):
                matrix[i] = matrix[i][1:] + [matrix[i][0]]
        elif op == 'R' or op == 'RIGHT':
            # Shift each row right
            for i in range(N):
                matrix[i] = [matrix[i][-1]] + matrix[i][:-1]
        elif op == 'U' or op == 'UP':
            # Shift each column up
            first_row = [matrix[0][j] for j in range(N)]
            for i in range(N - 1):
                for j in range(N):
                    matrix[i][j] = matrix[i+1][j]
            for j in range(N):
                matrix[N-1][j] = first_row[j]
        elif op == 'D' or op == 'DOWN':
            # Shift each column down
            last_row = [matrix[N-1][j] for j in range(N)]
            for i in range(N - 1, 0, -1):
                for j in range(N):
                    matrix[i][j] = matrix[i-1][j]
            for j in range(N):
                matrix[0][j] = last_row[j]

    for row in matrix:
        print(' '.join(map(str, row)))

